import java.util.*;import java.time.*;import javax.sql.DataSource;import java.math.BigDecimal;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.annotation.EnableTransactionManagement;import com.project.system.service.*;import com.project.web.controller.system.MerchantGatewayController;import org.springframework.http.ResponseEntity;import com.fasterxml.jackson.databind.*;
public class MerchantApiIntegration{
 @Configuration @EnableTransactionManagement static class Config{
 @Bean public DataSource dataSource(){return new DriverManagerDataSource("jdbc:mysql://127.0.0.1:13306/cc_api_test?useSSL=false&serverTimezone=Asia/Shanghai","root","");}@Bean public JdbcTemplate db(DataSource d){return new JdbcTemplate(d);}@Bean public DataSourceTransactionManager transactionManager(DataSource d){return new DataSourceTransactionManager(d);}@Bean public WalletService wallet(){return new WalletService();}@Bean public MerchantApiService api(){return new MerchantApiService();}@Bean public MerchantGatewayController gateway(){return new MerchantGatewayController();}}
 static int n;static ObjectMapper json=new ObjectMapper();static void check(boolean value,String name){if(!value)throw new AssertionError(name);n++;System.out.println("PASS "+name);}static JsonNode call(MerchantGatewayController g,String action,String body,String id,String secret)throws Exception{String t=String.valueOf(Instant.now().getEpochSecond()),nonce=UUID.randomUUID().toString();ResponseEntity<String> r=g.dispatch(action,body,id,t,nonce,ApiSecurity.sign(secret,t,nonce,"/api/v1/merchant/"+action,body));return json.readTree(r.getBody());}
 static Map<String,String> payload(String id,String name,String kind,String amount,String card){Map<String,String> p=new LinkedHashMap<>();p.put("merchantId",id);p.put("merchantName",name);p.put("requestId","REQ"+UUID.randomUUID().toString());p.put("tradeType",kind);p.put("amount",amount);p.put("occurredAt",OffsetDateTime.now(ZoneId.of("Asia/Shanghai")).withNano(0).toString());p.put("location","接口测试地点");p.put("cardNo",card);p.put("description","接口测试内容");return p;}
 public static void main(String[]args)throws Exception{try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(Config.class)){JdbcTemplate db=c.getBean(JdbcTemplate.class);WalletService w=c.getBean(WalletService.class);MerchantApiService api=c.getBean(MerchantApiService.class);MerchantGatewayController g=c.getBean(MerchantGatewayController.class);long mid=System.currentTimeMillis(),user=mid+1;String card="CC"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT);String student="API"+mid;db.update("insert into sys_user(user_id,login_name,user_name,status,del_flag) values(?,?,'接口测试用户','0','0')",user,student);db.update("insert into campus_card(user_id,card_no) values(?,?)",user,card);db.update("insert into campus_wallet(user_id,student_no,balance) values(?,?,20)",user,student);db.update("insert into campus_person_identity(user_id,identity_no) values(?,'11010519491231002X')",user);db.update("insert into campus_merchant(id,name,active) values(?,'接口测试商户',1)",mid);api.ensure(mid);Map<String,Object> config=api.config(mid);String id=(String)config.get("public_id");check(UUID.fromString(id).version()==4,"unguessable merchant UUID version 4");String secret=api.rotate(mid,1);api.configure(mid,true,false,true,"",1);
 Map<String,String> p=payload(id,"接口测试商户","PAY","1.25",card);String body=json.writeValueAsString(p);JsonNode created=call(g,"orders",body,id,secret);check("SUCCESS".equals(created.path("code").asText()),"signed fixed JSON creates order");String order=created.path("data").path("orderNo").asText();check(new BigDecimal("20").compareTo((BigDecimal)w.info(user).get("balance"))==0,"requesting order does not change balance");check(order.equals(call(g,"orders",body,id,secret).path("data").path("orderNo").asText()),"same request id returns original order");p.put("orderNo",order);p.put("localSerialNo","LOCAL"+UUID.randomUUID().toString());String execution=json.writeValueAsString(p);JsonNode paid=call(g,"execute",execution,id,secret);if(!"SUCCESS".equals(paid.path("code").asText()))throw new AssertionError(paid.toString());check(new BigDecimal("18.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"consumer balance debited and ledger returned");String ledger=paid.path("data").path("transactionNo").asText();check(ledger.equals(call(g,"execute",execution,id,secret).path("data").path("transactionNo").asText())&&new BigDecimal("18.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"retries do not debit twice");String nonce=UUID.randomUUID().toString(),time=String.valueOf(Instant.now().getEpochSecond()),sig=ApiSecurity.sign(secret,time,nonce,"/api/v1/merchant/query","{}");g.dispatch("query","{}",id,time,nonce,sig);check(g.dispatch("query","{}",id,time,nonce,sig).getStatusCodeValue()==401,"nonce replay rejected");check(g.dispatch("orders",body,id,time,UUID.randomUUID().toString(),sig).getStatusCodeValue()==401,"invalid signature rejected");check(g.dispatch("orders",body,UUID.randomUUID().toString(),time,nonce,sig).getStatusCodeValue()==401,"unknown merchant rejected");check(g.dispatch("orders",body,id,"1",nonce,sig).getStatusCodeValue()==401,"expired timestamp rejected");Map<String,String> mismatch=new LinkedHashMap<>(p);mismatch.put("amount","2.00");check("INVALID_REQUEST".equals(call(g,"execute",json.writeValueAsString(mismatch),id,secret).path("code").asText()),"order parameter tampering rejected");Map<String,String> bad=payload(id,"接口测试商户","PAY","100.00",card);String badOrder=call(g,"orders",json.writeValueAsString(bad),id,secret).path("data").path("orderNo").asText();bad.put("orderNo",badOrder);bad.put("localSerialNo","LOCAL"+UUID.randomUUID().toString());JsonNode failed=call(g,"execute",json.writeValueAsString(bad),id,secret);check("TRADE_FAILED".equals(failed.path("code").asText())&&"FAILED".equals(failed.path("data").path("status").asText()),"insufficient funds recorded as failed order");check(new BigDecimal("18.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"failed order leaves balance intact");Map<String,String> recharge=payload(id,"接口测试商户","RECHARGE","5.00",card);check("INVALID_REQUEST".equals(call(g,"orders",json.writeValueAsString(recharge),id,secret).path("code").asText()),"recharge permission initially denied");api.configure(mid,true,true,true,"",1);String rechargeOrder=call(g,"orders",json.writeValueAsString(recharge),id,secret).path("data").path("orderNo").asText();recharge.put("orderNo",rechargeOrder);recharge.put("localSerialNo","LOCAL"+UUID.randomUUID().toString());w.status(user,"LOST");JsonNode charged=call(g,"execute",json.writeValueAsString(recharge),id,secret);check("SUCCESS".equals(charged.path("code").asText())&&new BigDecimal("23.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"authorized recharge works for lost wallet");check(db.queryForObject("select count(*) from campus_recharge_order where order_no=?",Integer.class,rechargeOrder)==1,"recharge order links to existing recharge ledger");check(db.queryForObject("select count(*) from campus_api_log where public_id=? and code<>'SUCCESS'",Integer.class,id)>=5,"failed communications persisted");db.update("update campus_api_credential set callback_url='https://example.com/notify' where merchant_id=?",mid);w.status(user,"ACTIVE");Map<String,String> notify=payload(id,"接口测试商户","PAY","0.01",card);String no=call(g,"orders",json.writeValueAsString(notify),id,secret).path("data").path("orderNo").asText();notify.put("orderNo",no);notify.put("localSerialNo","LOCAL"+UUID.randomUUID().toString());call(g,"execute",json.writeValueAsString(notify),id,secret);check(db.queryForObject("select count(*) from campus_api_outbox where order_no=? and status='PENDING'",Integer.class,no)==1,"transaction result notification durably queued without sending");api.configure(mid,false,true,true,"",1);check("AUTH_FAILED".equals(call(g,"query",json.writeValueAsString(new LinkedHashMap<String,String>(){{put("merchantId",id);put("orderNo",order);}}),id,secret).path("code").asText()),"disabled interface rejected");System.out.println("PASS TOTAL "+n);}}
}
